// Review P1-10: roster/llms.txt (short index) and roster/llms-full.txt (summaries and method), both
// generated by the build so every URL follows SITE_ORIGIN/SITE_BASE. No company contact data.
import {absUrl} from './site-config.mjs';

const line = (label, path, note) => `- [${label}](${absUrl(path)})${note ? `: ${note}` : ''}`;

export function renderLlms({trades, guides, posts, bestPath, bestLabel, best, dataDate, counts}) {
  const hubs = trades.map(t => line(t.name, `/${t.slug}/`, `${counts[t.id]} companies, with sourced prices, ratings and service areas.`));
  const bests = trades.map(t => line(bestLabel(t.id), bestPath(t.id), `ranked on the Google Maps rating with at least ${best.minReviews} reviews; score = (reviews × rating + ${best.K} × ${best.m}) ÷ (reviews + ${best.K}).`));
  const short = [
    '# HomezyPro',
    '',
    '> HomezyPro is an unpaid directory of home-service companies in Singapore (aircon servicing, plumbing, electrical, handyman and home cleaning). Every price, rating and service area links to the company website or rating source it came from. Listings are unpaid and there is no commission.',
    '',
    '## Trade directories',
    ...hubs,
    '',
    '## Guides and tools',
    line('Aircon servicing prices', '/aircon/servicing-price/', 'published rates by unit size (BTU), with sources.'),
    line('What service do I need?', '/what-service-do-i-need/', 'match a home problem to the service to ask for.'),
    line('Home advice blog', '/blog/', `${posts.length} articles with official sources.`),
    '',
    '## Ranked lists',
    ...bests,
    '',
    '## Method',
    line('How HomezyPro works', '/how-it-works/', 'how listings, prices, ratings and coverage are sourced.'),
    `- Ratings: the headline rating is the Google Maps rating. Other sources are shown separately and never averaged in; self-reported scores are plain sentences.`,
    `- Prices: each figure is one company's own published rate with its conditions, not a quote or a market average.`,
    `- Data release: ${dataDate}.`,
    '',
    `More detail: ${absUrl('/llms-full.txt')}`,
    ''
  ].join('\n');
  const byTrade = trades.map(t => {
    const list = guides.filter(g => g.trade === t.id);
    return [`## ${t.name}`, '', line(`${t.name} directory`, `/${t.slug}/`, `${counts[t.id]} companies.`), line(bestLabel(t.id), bestPath(t.id)), ...list.map(g => line(g.label, g.path, g.description)), ''].join('\n');
  });
  const full = [
    short.split('\nMore detail:')[0].trim(),
    '',
    '# Guides by trade',
    '',
    ...byTrade,
    '# Blog',
    '',
    ...posts.map(p => line(p.label, p.path, p.description)),
    '',
    '# How the data is collected',
    '',
    '- Companies: published only when their own website or a cited record supports the trade, services and contact details. Thin or unconfirmed profiles are marked as limited.',
    '- Prices: copied from the company\'s own pages with the source link. "From" marks a starting price; ranges and units are kept as printed; promotions and indicative figures are left out of comparisons.',
    '- Ratings: Google Maps rating and review count as HomezyPro recorded them. Trustpilot, Carousell, Yelp, review mirrors and self-reported scores are never blended in.',
    '- Coverage: a company is listed for a town only when its own website names that town. Office addresses are not used as service areas.',
    `- Ranked lists: score = (reviews × rating + ${best.K} × ${best.m}) ÷ (reviews + ${best.K}), minimum ${best.minReviews} Google reviews; no paid placement and no manual changes.`,
    ''
  ].join('\n');
  return {short, full};
}
